    mod twin_sync {
        use std::path::PathBuf;
        extern crate test;
        #[rustc_test_marker = "scalars::int4::twin_sync::ordered_int4_domain_files_stay_in_sync"]
        #[doc(hidden)]
        pub const ordered_int4_domain_files_stay_in_sync: test::TestDescAndFn = test::TestDescAndFn {
            desc: test::TestDesc {
                name: test::StaticTestName(
                    "scalars::int4::twin_sync::ordered_int4_domain_files_stay_in_sync",
                ),
                ignore: false,
                ignore_message: ::core::option::Option::None,
                source_file: "tests/encrypted_domain/scalars/int4.rs",
                start_line: 35usize,
                start_col: 8usize,
                end_line: 35usize,
                end_col: 46usize,
                compile_fail: false,
                no_run: false,
                should_panic: test::ShouldPanic::No,
                test_type: test::TestType::IntegrationTest,
            },
            testfn: test::StaticTestFn(
                #[coverage(off)]
                || test::assert_test_result(ordered_int4_domain_files_stay_in_sync()),
            ),
        };
        /// Structural-sync guard for the two ordered int4 domain file pairs.
        ///
        /// `_ord_ore` (scheme-explicit) and `_ord` (D-E fallback concrete domain)
        /// are deliberate twins: same `eql_v2.ord_term` extractor, the 18
        /// comparison wrappers, the blockers, and the operator declarations,
        /// differing only by the `eql_v2_int4_ord_ore` <-> `eql_v2_int4_ord`
        /// type-name swap. After normalising both type names to a common token,
        /// the executable body of each file (file-header doc comments excluded)
        /// must be byte-identical between the twins.
        ///
        /// The build regenerates `src/encrypted_domain/int4/` from
        /// `tasks/codegen/types/int4.toml` (gitignored). This test runs against
        /// the materialised files and requires the build to have run.
        fn ordered_int4_domain_files_stay_in_sync() {
            fn body(rel: &str, marker: &str) -> String {
                let path = PathBuf::from(
                        "/Users/tobyhede/src/encrypt-query-language/.worktrees/int4/variant-family/tests/sqlx",
                    )
                    .join("../../src/encrypted_domain/int4")
                    .join(rel);
                let text = std::fs::read_to_string(&path)
                    .unwrap_or_else(|e| {
                        ::core::panicking::panic_fmt(
                            format_args!("failed to read {0}: {1}", path.display(), e),
                        );
                    });
                let start = text
                    .find(marker)
                    .unwrap_or_else(|| {
                        ::core::panicking::panic_fmt(
                            format_args!(
                                "{0} is missing the marker {1:?}",
                                path.display(),
                                marker,
                            ),
                        );
                    });
                text[start..]
                    .replace("eql_v2_int4_ord_ore", "ORDTYPE")
                    .replace("eql_v2_int4_ord", "ORDTYPE")
            }
            match (
                &body("int4_ord_ore_functions.sql", "CREATE FUNCTION eql_v2.ord_term"),
                &body("int4_ord_functions.sql", "CREATE FUNCTION eql_v2.ord_term"),
            ) {
                (left_val, right_val) => {
                    if !(*left_val == *right_val) {
                        let kind = ::core::panicking::AssertKind::Eq;
                        ::core::panicking::assert_failed(
                            kind,
                            &*left_val,
                            &*right_val,
                            ::core::option::Option::Some(
                                format_args!(
                                    "int4_ord_ore_functions.sql and int4_ord_functions.sql have drifted apart. They must stay mechanical twins (type-name swap only) below the file header; mirror every change into both files.",
                                ),
                            ),
                        );
                    }
                }
            };
            match (
                &body("int4_ord_ore_operators.sql", "CREATE OPERATOR"),
                &body("int4_ord_operators.sql", "CREATE OPERATOR"),
            ) {
                (left_val, right_val) => {
                    if !(*left_val == *right_val) {
                        let kind = ::core::panicking::AssertKind::Eq;
                        ::core::panicking::assert_failed(
                            kind,
                            &*left_val,
                            &*right_val,
                            ::core::option::Option::Some(
                                format_args!(
                                    "int4_ord_ore_operators.sql and int4_ord_operators.sql have drifted apart. They must stay mechanical twins (type-name swap only) below the file header; mirror every change into both files.",
                                ),
                            ),
                        );
                    }
                }
            };
            match (
                &body("int4_ord_ore_aggregates.sql", "CREATE FUNCTION eql_v2.min_sfunc"),
                &body("int4_ord_aggregates.sql", "CREATE FUNCTION eql_v2.min_sfunc"),
            ) {
                (left_val, right_val) => {
                    if !(*left_val == *right_val) {
                        let kind = ::core::panicking::AssertKind::Eq;
                        ::core::panicking::assert_failed(
                            kind,
                            &*left_val,
                            &*right_val,
                            ::core::option::Option::Some(
                                format_args!(
                                    "int4_ord_ore_aggregates.sql and int4_ord_aggregates.sql have drifted apart. They must stay mechanical twins (type-name swap only) below the file header; mirror every change into both files.",
                                ),
                            ),
                        );
                    }
                }
            };
        }
    }
